Rules.InvariantScript:
If(!varCargado,
    Concurrent(
        ClearCollect(colPersonal, tblPersonal),
        If(IsError(ClearCollect(colIngresos, tblIngresos)), false),
        ClearCollect(colHistorial, tblHistorial),
        ClearCollect(colDonantes, tblDonantes)
    );
    Set(varYo, LookUp(colPersonal, Lower(Trim(Correo)) = Lower(User().Email) && Activo = "Sí"));
    Set(varArea, If(IsBlank(varYo), "Sin acceso", varYo.Area));
    Set(varCargado, true)
);
If(IsBlank(varTema), Set(varTema, "claro"));
IfError(ClearCollect(colInvTodos, Filter(tblInventario, Id <> "0")); true, Notify("No se pudo leer tblInventario (App_Biblioteca_Datos.xlsx). En Power Apps: Datos → tblInventario → ⋯ → Actualizar.", NotificationType.Error); false);
If(IsBlank(varInvCargando), Set(varInvCargando, false); Set(varCodInv, ""); ClearCollect(colEsperados, FirstN(Table({codigo: "", titulo: "", dewey: "", cutter: "", estado: ""}), 0)); ClearCollect(colTotales, FirstN(Table({bib: "", n: 0}), 0)))

If(IsBlank(Trim(txtDesdeIv.Text)) || IsBlank(Trim(txtHastaIv.Text)), Notify("Indique el rango Dewey del estante (desde y hasta).", NotificationType.Warning),
    Set(varEstante, drpBibIv.Selected.Value & " · " & Trim(txtDesdeIv.Text) & "–" & Trim(txtHastaIv.Text));
    Set(varInvCargando, true);
    Set(varInvRes, IfError('FolioInventario'.Run(drpBibIv.Selected.Value, Trim(txtDesdeIv.Text), Trim(txtHastaIv.Text)), Notify("No se pudo consultar FOLIO (flujo FolioInventario): " & FirstError.Message, NotificationType.Error); Blank()));
    Set(varInvCargando, false);
    If(IsBlank(varInvRes), Notify("No se pudo consultar FOLIO. Revise el flujo FolioInventario.", NotificationType.Error),
        ClearCollect(colEsperados, ForAll(Table(ParseJSON(Coalesce(varInvRes.datos, "[]"))), {codigo: Text(ThisRecord.Value.codigo), titulo: Text(ThisRecord.Value.titulo), dewey: Text(ThisRecord.Value.dewey), cutter: Text(ThisRecord.Value.cutter), estado: Text(ThisRecord.Value.estado)}));
        ClearCollect(colTotales, ForAll(Table(ParseJSON(Coalesce(varInvRes.totales, "[]"))), {bib: Text(ThisRecord.Value.bib), n: Value(ThisRecord.Value.n)}));
        Notify("Estante cargado: " & CountRows(colEsperados) & " ejemplares esperados según FOLIO.", NotificationType.Success); SetFocus(txtEscanIv)))
